const items = $input.all();

function isNumeric(val) {
  if (typeof val === 'number') return !isNaN(val) && isFinite(val);
  if (typeof val !== 'string') return false;
  const trimmed = val.trim();
  if (trimmed === '') return false;
  const num = Number(trimmed);
  return !isNaN(num) && isFinite(num);
}

function parseNumeric(val) {
  if (typeof val === 'number') return val;
  return Number(String(val).trim());
}

return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];

  const requestId = data.request_id || "REQ-FIN-DEMO";
  const tenderId = data.tender_id || "TENDER-FIN-DEMO";
  const bidderId = data.bidder_id || "BIDDER-FIN-DEMO";
  const bidderName = (data.bidder_name || "ABC Technologies Pvt Ltd").toString().trim();

  const reqs = data.financial_requirements || {};
  const parsedReqs = {};

  // Validate requirements numbers
  for (const [key, val] of Object.entries(reqs)) {
    if (val !== null && val !== undefined) {
      if (!isNumeric(val)) {
        errors.push(`Invalid financial requirement: '${key}' must be a valid number, received '${val}'`);
      } else {
        const num = parseNumeric(val);
        if (num < 0) {
          errors.push(`Invalid financial requirement: '${key}' cannot be negative (${num})`);
        } else {
          parsedReqs[key] = num;
        }
      }
    }
  }

  // Set default period to 3 years if average turnover required but period unspecified
  if (parsedReqs.average_turnover !== undefined && !parsedReqs.turnover_period_years) {
    parsedReqs.turnover_period_years = 3;
  }

  const evidence = data.financial_evidence || null;
  let parsedEvidence = null;

  if (evidence && typeof evidence === 'object') {
    parsedEvidence = {};

    // Turnover
    if (evidence.turnover !== undefined && evidence.turnover !== null) {
      if (typeof evidence.turnover === 'object' && !Array.isArray(evidence.turnover)) {
        parsedEvidence.turnover = {};
        for (const [year, val] of Object.entries(evidence.turnover)) {
          if (!isNumeric(val)) {
            errors.push(`Invalid financial data: turnover for year '${year}' contains non-numeric value '${val}'`);
          } else {
            const num = parseNumeric(val);
            if (num < 0) {
              errors.push(`Invalid financial data: turnover for year '${year}' cannot be negative (${num})`);
            } else {
              parsedEvidence.turnover[year] = num;
            }
          }
        }
      } else if (Array.isArray(evidence.turnover)) {
        parsedEvidence.turnover = {};
        evidence.turnover.forEach((val, idx) => {
          const yearKey = `Year_${idx + 1}`;
          if (!isNumeric(val)) {
            errors.push(`Invalid financial data: turnover item at index ${idx} contains non-numeric value '${val}'`);
          } else {
            const num = parseNumeric(val);
            if (num < 0) {
              errors.push(`Invalid financial data: turnover cannot be negative (${num})`);
            } else {
              parsedEvidence.turnover[yearKey] = num;
            }
          }
        });
      } else {
        errors.push(`Invalid financial data: 'turnover' must be an object with year keys or an array, received '${evidence.turnover}'`);
      }
    }

    // Net Worth
    if (evidence.net_worth !== undefined && evidence.net_worth !== null) {
      if (!isNumeric(evidence.net_worth)) {
        errors.push(`Invalid financial data: 'net_worth' must be a valid number, received '${evidence.net_worth}'`);
      } else {
        parsedEvidence.net_worth = parseNumeric(evidence.net_worth);
      }
    }

    // Working Capital
    if (evidence.working_capital !== undefined && evidence.working_capital !== null) {
      if (!isNumeric(evidence.working_capital)) {
        errors.push(`Invalid financial data: 'working_capital' must be a valid number, received '${evidence.working_capital}'`);
      } else {
        parsedEvidence.working_capital = parseNumeric(evidence.working_capital);
      }
    }
  }

  return {
    json: {
      request_id: requestId,
      tender_id: tenderId,
      bidder_id: bidderId,
      bidder_name: bidderName,
      financial_requirements: parsedReqs,
      financial_evidence: parsedEvidence,
      raw_evidence_provided: !!evidence,
      validation_errors: errors,
      valid_schema: errors.length === 0,
      raw_input: data
    }
  };
});

const items = $input.all();

// Mock financial filings registry database
