return items.map(item => {
  const data = item.json;

  if (!data.valid_schema) {
    return { json: { ...data, registry_record: null } };
  }

  let resolvedEvidence = data.financial_evidence;
  let registryRecord = null;

  // If explicit evidence was not provided or incomplete, supplement from registry
  if (!data.raw_evidence_provided || (!resolvedEvidence || Object.keys(resolvedEvidence).length === 0)) {
    registryRecord = MOCK_FINANCIAL_REGISTRY[data.bidder_name] || null;
    if (registryRecord) {
      resolvedEvidence = {
        turnover: registryRecord.turnover,
        net_worth: registryRecord.net_worth,
        working_capital: registryRecord.working_capital
      };
    }
  }

  return {
    json: {
      ...data,
      resolved_evidence: resolvedEvidence,
      registry_record: registryRecord
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  if (!data.valid_schema) {
    return {
      json: {
        ...data,
        calculated_metrics: null,
        compliance_checks: [],
        calculation_error: data.validation_errors
      }
    };
  }

  const reqs = data.financial_requirements || {};
  const evidence = data.resolved_evidence || {};
  const checks = [];
  const issues = [];

  let turnoverByYear = null;
  let avgTurnover = null;
  let turnoverSum = 0;
  let yearCount = 0;

  // 1. Turnover Evaluation
  if (evidence.turnover && typeof evidence.turnover === 'object' && Object.keys(evidence.turnover).length > 0) {
    turnoverByYear = evidence.turnover;
    const years = Object.keys(turnoverByYear).sort();
    const periodYears = reqs.turnover_period_years || years.length || 3;

    // Take the most recent periodYears
    const evalYears = years.slice(-periodYears);
    evalYears.forEach(y => {
      turnoverSum += turnoverByYear[y];
      yearCount++;
    });

    avgTurnover = yearCount > 0 ? (turnoverSum / yearCount) : null;

    // Rule: AVERAGE_TURNOVER
    if (reqs.average_turnover !== undefined && reqs.average_turnover !== null) {
      const passed = avgTurnover !== null && avgTurnover >= reqs.average_turnover;
      checks.push({
        rule: "AVERAGE_TURNOVER",
        required: reqs.average_turnover,
        actual: avgTurnover,
        period_years: yearCount,
        result: passed ? "PASS" : "FAIL"
      });
      if (!passed) {
        issues.push(`Average turnover ₹${avgTurnover !== null ? avgTurnover.toLocaleString('en-IN') : 0} is below required minimum ₹${reqs.average_turnover.toLocaleString('en-IN')}`);
      }
    }

    // Rule: MINIMUM_ANNUAL_TURNOVER (every year must satisfy)
    if (reqs.minimum_annual_turnover !== undefined && reqs.minimum_annual_turnover !== null) {
      let allYearsPass = true;
      const failingYears = [];

      evalYears.forEach(y => {
        if (turnoverByYear[y] < reqs.minimum_annual_turnover) {
          allYearsPass = false;
          failingYears.push(`${y}: ₹${turnoverByYear[y].toLocaleString('en-IN')}`);
        }
      });

      checks.push({
        rule: "MINIMUM_ANNUAL_TURNOVER",
        required: reqs.minimum_annual_turnover,
        actual: evalYears.map(y => ({ year: y, turnover: turnoverByYear[y] })),
        result: allYearsPass ? "PASS" : "FAIL"
      });

      if (!allYearsPass) {
        issues.push(`Annual turnover failed minimum threshold (₹${reqs.minimum_annual_turnover.toLocaleString('en-IN')}) in year(s): ${failingYears.join(', ')}`);
      }
    }
  } else {
    // Check if turnover was required but completely missing
    if (reqs.average_turnover !== undefined || reqs.minimum_annual_turnover !== undefined) {
      checks.push({
        rule: "TURNOVER_EVIDENCE",
        required: reqs.average_turnover || reqs.minimum_annual_turnover,
        actual: null,
        result: "MISSING"
      });
      issues.push("Required turnover evidence is missing");
    }
  }

  // 2. Net Worth Evaluation
  if (reqs.minimum_net_worth !== undefined && reqs.minimum_net_worth !== null) {
    if (evidence.net_worth !== undefined && evidence.net_worth !== null) {
      const passed = evidence.net_worth >= reqs.minimum_net_worth;
      checks.push({
        rule: "MINIMUM_NET_WORTH",
        required: reqs.minimum_net_worth,
        actual: evidence.net_worth,
        result: passed ? "PASS" : "FAIL"
      });
      if (!passed) {
        issues.push(`Net worth ₹${evidence.net_worth.toLocaleString('en-IN')} is below required minimum ₹${reqs.minimum_net_worth.toLocaleString('en-IN')}`);
      }
    } else {
      checks.push({
        rule: "MINIMUM_NET_WORTH",
        required: reqs.minimum_net_worth,
        actual: null,
        result: "MISSING"
      });
      issues.push("Required net worth evidence is missing");
    }
  }

  // 3. Working Capital Evaluation
  if (reqs.minimum_working_capital !== undefined && reqs.minimum_working_capital !== null) {
    if (evidence.working_capital !== undefined && evidence.working_capital !== null) {
      const passed = evidence.working_capital >= reqs.minimum_working_capital;
      checks.push({
        rule: "MINIMUM_WORKING_CAPITAL",
        required: reqs.minimum_working_capital,
        actual: evidence.working_capital,
        result: passed ? "PASS" : "FAIL"
      });
      if (!passed) {
        issues.push(`Working capital ₹${evidence.working_capital.toLocaleString('en-IN')} is below required minimum ₹${reqs.minimum_working_capital.toLocaleString('en-IN')}`);
      }
    } else {
      checks.push({
        rule: "MINIMUM_WORKING_CAPITAL",
        required: reqs.minimum_working_capital,
        actual: null,
        result: "MISSING"
      });
      issues.push("Required working capital evidence is missing");
    }
  }

  return {
    json: {
      ...data,
      calculated_metrics: {
        turnover_by_year: turnoverByYear,
        average_turnover: avgTurnover,
        turnover_sum: turnoverSum,
        years_evaluated: yearCount,
        net_worth: evidence.net_worth !== undefined ? evidence.net_worth : null,
        working_capital: evidence.working_capital !== undefined ? evidence.working_capital : null
      },
      compliance_checks: checks,
      evaluation_issues: issues
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  let status = "VERIFIED";
  let confidence = 0.99;
  let riskLevel = "LOW";
  const issues = [];

  // 1. Check for schema/data corruption errors
  if (!data.valid_schema) {
    status = "ERROR";
    confidence = 0.0;
    riskLevel = "HIGH";
    issues.push(...(data.validation_errors || ["Invalid financial data encountered"]));
  } else {
    const checks = data.compliance_checks || [];
    const evalIssues = data.evaluation_issues || [];

    const hasFails = checks.some(c => c.result === "FAIL");
    const hasMissing = checks.some(c => c.result === "MISSING");

    issues.push(...evalIssues);

    if (hasFails) {
      status = "NOT_VERIFIED";
      confidence = 0.99;
      riskLevel = "HIGH";
    } else if (hasMissing) {
      status = "NOT_VERIFIED";
      confidence = 0.95;
      riskLevel = "HIGH";
    } else if (checks.length === 0) {
      // No financial requirements specified in tender
      status = "VERIFIED";
      confidence = 0.95;
      riskLevel = "LOW";
    } else {
      status = "VERIFIED";
      confidence = 0.99;
      riskLevel = "LOW";
    }
  }

  const metrics = data.calculated_metrics || {};
  const reqs = data.financial_requirements || {};

  return {
    json: {
      agent: "FINANCIAL_AGENT",
      status,
      confidence,
      evidence: {
        turnover_by_year: metrics.turnover_by_year || null,
        average_turnover: metrics.average_turnover || null,
        required_average_turnover: reqs.average_turnover || null,
        required_minimum_annual_turnover: reqs.minimum_annual_turnover || null,
        net_worth: metrics.net_worth !== undefined ? metrics.net_worth : null,
        required_net_worth: reqs.minimum_net_worth || null,
        working_capital: metrics.working_capital !== undefined ? metrics.working_capital : null,
        required_working_capital: reqs.minimum_working_capital || null,
        years_evaluated: metrics.years_evaluated || 0,
        checks: data.compliance_checks || [],
        ca_certified: data.registry_record ? data.registry_record.ca_certified : null,
        udin: data.registry_record ? data.registry_record.udin : null,
        registry_source: data.registry_record ? data.registry_record.source : "BIDDER_SUBMISSION"
      },
      issues,
      risk_level: riskLevel,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: item.json
}));

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "FINANCIAL_AGENT",
    status: "ERROR",
    confidence: 0.0,
    evidence: {
      error: "Financial verification agent encountered an unexpected execution failure",
      fallback_mode: true
    },
    issues: ["Financial verification agent failed unexpectedly"],
    risk_level: "HIGH",
    timestamp: new Date().toISOString()
  }
}));
